package com.bank.vthreads;

import java.math.BigDecimal;
import java.util.logging.Logger;

// BAD for virtual threads: blocking I/O INSIDE synchronized pins the carrier thread.
class PinningLedger {
    private static final Logger log = Logger.getLogger(PinningLedger.class.getName());
    private BigDecimal balance = new BigDecimal("1000000");   // Rajesh SAV2001

    // The monitor is bound to the CARRIER platform thread. The blocking call inside
    // means the virtual thread CANNOT unmount → the carrier is held hostage.
    synchronized void debit(BigDecimal amount) {
        simulateBlockingDbCall();        // blocking I/O inside synchronized → PINS
        balance = balance.subtract(amount);
    }

    private void simulateBlockingDbCall() {
        try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
    BigDecimal balance() { return balance; }
}
