package com.bank.vthreads;

import java.math.BigDecimal;
import java.util.concurrent.locks.ReentrantLock;
import java.util.logging.Logger;

// GOOD for virtual threads: ReentrantLock lets the virtual thread UNMOUNT while it
// blocks, so the small carrier pool stays free for other virtual threads.
class NonPinningLedger {
    private static final Logger log = Logger.getLogger(NonPinningLedger.class.getName());
    private final ReentrantLock lock = new ReentrantLock();
    private BigDecimal balance = new BigDecimal("1000000");   // Rajesh SAV2001

    void debit(BigDecimal amount) {
        lock.lock();                     // waiting here does NOT pin the carrier
        try {
            simulateBlockingDbCall();    // virtual thread can unmount during this block
            balance = balance.subtract(amount);
        } finally {
            lock.unlock();               // always release in finally
        }
    }

    private void simulateBlockingDbCall() {
        try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
    BigDecimal balance() { return balance; }
}
