package com.bank.vthreads;

import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.logging.Logger;

public class PinningDemo {
    private static final Logger log = Logger.getLogger(PinningDemo.class.getName());

    public static void main(String[] args) throws Exception {
        int tasks = 500;

        // Version A: synchronized ledger (pins carriers under blocking I/O)
        PinningLedger pinning = new PinningLedger();
        long a = runAll(tasks, () -> pinning.debit(new BigDecimal("1")));
        log.warning(() -> "synchronized (PINS): " + a + "ms, balance=Rs." + pinning.balance());

        // Version B: ReentrantLock ledger (no pinning, carriers stay free)
        NonPinningLedger nonPinning = new NonPinningLedger();
        long b = runAll(tasks, () -> nonPinning.debit(new BigDecimal("1")));
        log.info(() -> "ReentrantLock (NO PIN): " + b + "ms, balance=Rs." + nonPinning.balance());
    }

    // One virtual thread PER task — never pool virtual threads, they are cheap.
    private static long runAll(int tasks, Runnable job) throws InterruptedException {
        long start = System.currentTimeMillis();
        try (ExecutorService vexec = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < tasks; i++) vexec.submit(job);
        }  // close() waits for all virtual threads to finish
        return System.currentTimeMillis() - start;
    }
}
